SELECT role_id AS subject_id, permission_id AS target_id, state, granted_at, revoked_at, lock_version
FROM role_permission
WHERE tenant_id = #{tenantId} AND role_id = #{roleId} AND permission_id = #{permissionId}

SELECT user_id AS subject_id, role_id AS target_id, state, granted_at, revoked_at, lock_version
FROM user_role_assignment
WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND role_id = #{roleId}

SELECT role_id AS subject_id, permission_id AS target_id, state, granted_at, revoked_at, lock_version
FROM role_permission WHERE tenant_id = #{tenantId} AND role_id = #{roleId}
AND state = #{state}
ORDER BY permission_id

SELECT user_id AS subject_id, role_id AS target_id, state, granted_at, revoked_at, lock_version
FROM user_role_assignment WHERE tenant_id = #{tenantId} AND user_id = #{userId}
AND state = #{state}
ORDER BY role_id

